using System;using System.Collections.ObjectModel;using System.ComponentModel;using System.IO;using System.Runtime.CompilerServices;using System.Windows;using Microsoft.Win32;using SAUDICO.Federate.Core;using SAUDICO.Federate.Export;using SAUDICO.Federate.Shared;namespace SAUDICO.Federate.UI;public partial class Manager:Window,INotifyPropertyChanged{readonly Action<Job,Action<Result>,Action<string>> enqueue;readonly SettingsService settingsService=new SettingsService();string output="",log="Ready.";ExportSettings settings;public ObservableCollection<Job> Jobs{get;}=new();public Array Params=>Enum.GetValues(typeof(ParamMode));public Array Coords=>Enum.GetValues(typeof(CoordMode));public Array Details=>Enum.GetValues(typeof(DetailMode));public ExportSettings Settings{get=>settings;set{settings=value;On();}}public string Output{get=>output;set{output=value;On();}}public string Log{get=>log;set{log=value;On();}}public Manager(Action<Job,Action<Result>,Action<string>> q){InitializeComponent();enqueue=q;settings=settingsService.Load();DataContext=this;}void Add(object s,RoutedEventArgs e){var d=new OpenFileDialog{Filter="Revit (*.rvt)|*.rvt",Multiselect=true};if(d.ShowDialog()==true)foreach(var f in d.FileNames)Jobs.Add(new Job{Source=f,Kind=Detector.Get(f)});}void Remove(object s,RoutedEventArgs e){if(GridJobs.SelectedItem is Job j)Jobs.Remove(j);}void Clear(object s,RoutedEventArgs e)=>Jobs.Clear();void Folder(object s,RoutedEventArgs e){using var d=new System.Windows.Forms.FolderBrowserDialog();if(d.ShowDialog()==System.Windows.Forms.DialogResult.OK)Output=d.SelectedPath;}void Props(object s,RoutedEventArgs e){if(!Settings.Properties)Settings.Parameters=ParamMode.None;}void Defaults(object s,RoutedEventArgs e)=>Settings=ExportSettings.Default();void SaveDefault(object s,RoutedEventArgs e){settingsService.Save(Settings);Append("User default saved to settings.json");}void Run(object s,RoutedEventArgs e){settingsService.Save(Settings);if(Jobs.Count==0||!Directory.Exists(Output)){MessageBox.Show("Add RVT files and select output folder.");return;}if(Settings.Faceting<.1||Settings.Faceting>10){MessageBox.Show("Faceting Factor must be 0.10–10.00.");return;}int i=0;Action next=null!;next=()=>{if(i>=Jobs.Count){if(Settings.Csv)Append("CSV: "+Report.Write(Output,Jobs));return;}var j=Jobs[i++];j.OutputFolder=Output;j.Settings=Settings.Copy();enqueue(j,res=>Dispatcher.Invoke(()=>{j.Output=res.Path;j.Error=res.Error;j.State=res.Skipped?State.Skipped:res.Ok?State.Succeeded:State.Failed;next();}),m=>Dispatcher.Invoke(()=>Append(j.Name+": "+m)));};next();}void Append(string s)=>Log+=Environment.NewLine+DateTime.Now.ToString("HH:mm:ss")+"  "+s;public event PropertyChangedEventHandler? PropertyChanged;void On([CallerMemberName]string? n=null)=>PropertyChanged?.Invoke(this,new PropertyChangedEventArgs(n));}